// src/lib/mcp/tools/search-blog.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z4 } from "npm:zod@^3.25.76";
import { blogPosts as blogPosts3 } from "npm:@/data/blogPosts";
var search_blog_default = defineTool4({
  name: "search_blog",
  title: "Search blog",
  description: "Full-text search across CognitionX blog posts (title, description, tags, body). Case-insensitive substring match. Returns matching posts with slug, title, and a short snippet.",
  inputSchema: {
    query: z4.string().min(1).describe("Search query (Russian or English)."),
    limit: z4.number().int().min(1).max(50).optional().describe("Max results (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.toLowerCase();
    const results = blogPosts3.map((p) => {
      const body = p.content.map((b) => b.text).join(" ").replace(/<[^>]+>/g, " ");
      const haystack = `${p.title}
${p.description}
${p.tags.join(" ")}
${body}`.toLowerCase();
      const idx = haystack.indexOf(q);
      if (idx === -1) return null;
      const snippet = haystack.slice(Math.max(0, idx - 80), idx + 200).replace(/\s+/g, " ").trim();
      return {
        slug: p.slug,
        title: p.title,
        description: p.description,
        tags: p.tags,
        url: `https://cognitionx.cloud/blog/${p.slug}`,
        snippet: `\u2026${snippet}\u2026`
      };
    }).filter((x) => x !== null).slice(0, limit ?? 10);
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      structuredContent: { results, total: results.length }
    };
  }
});

